{
  "name": "量子比特抽象控制对象",
  "name_en": "Abstract Qubit Control Object",
  "manufacturer": "",
  "description": "一个非物理的量子比特实验控制组件，用作量子比特参数容器和测量流程模板。它为超导量子比特实验统一组织 T1、Rabi、Ramsey、回波、单次读出、频谱、谐振腔搜索、通量调谐与多种校准流程，本身不是可独立连接的硬件仪器，而是供具体量子比特实现类继承的抽象基类。",
  "description_en": "A non-physical qubit experiment control component that serves as a parameter container and measurement template for a qubit. It organizes T1, Rabi, Ramsey, echo, single-shot readout, spectroscopy, resonator search, flux tuning, and calibration workflows for superconducting qubit experiments. It is not a standalone hardware instrument, but an abstract base class intended for concrete qubit implementations.",
  "tag_hints": [
    "superconducting qubit control",
    "qubit calibration",
    "time-domain qubit measurements",
    "Ramsey and T1 experiments",
    "readout resonator characterization",
    "flux bias tuning",
    "single-shot readout"
  ],
  "actions": [
    {
      "action_name": "auto-connect_message",
      "description": "显示该量子比特控制对象的连接信息。",
      "description_en": "Display the connection message for this qubit control object."
    },
    {
      "action_name": "auto-get_idn",
      "description": "获取该量子比特控制对象的标识信息。",
      "description_en": "Get the identification information of this qubit control object."
    },
    {
      "action_name": "auto-add_instrument_ref_parameters",
      "description": "定义对相关实验仪器的引用参数。",
      "description_en": "Define reference parameters to related laboratory instruments."
    },
    {
      "action_name": "auto-add_ro_parameters",
      "description": "定义读出相关参数。",
      "description_en": "Define readout-related parameters."
    },
    {
      "action_name": "auto-add_mw_parameters",
      "description": "定义微波控制相关参数。",
      "description_en": "Define microwave-control-related parameters."
    },
    {
      "action_name": "auto-add_spec_parameters",
      "description": "定义频谱测量相关参数。",
      "description_en": "Define spectroscopy-related parameters."
    },
    {
      "action_name": "auto-add_flux_parameters",
      "description": "定义通量控制相关参数。",
      "description_en": "Define flux-control-related parameters."
    },
    {
      "action_name": "auto-add_config_parameters",
      "description": "定义配置参数。",
      "description_en": "Define configuration parameters."
    },
    {
      "action_name": "auto-add_generic_qubit_parameters",
      "description": "定义通用量子比特参数。",
      "description_en": "Define generic qubit parameters."
    },
    {
      "action_name": "auto-measure_T1",
      "description": "通过实验装置执行量子比特 T1 弛豫测量。",
      "description_en": "Run a qubit T1 relaxation measurement through the experimental setup."
    },
    {
      "action_name": "auto-measure_rabi",
      "description": "通过实验装置执行量子比特 Rabi 振荡测量。",
      "description_en": "Run a qubit Rabi oscillation measurement through the experimental setup."
    },
    {
      "action_name": "auto-measure_flipping",
      "description": "执行重复翻转脉冲实验以检查门操作表现。",
      "description_en": "Run a repeated flipping-pulse experiment to check gate performance."
    },
    {
      "action_name": "auto-measure_ramsey",
      "description": "执行 Ramsey 实验以估计 T2* 和量子比特频率。",
      "description_en": "Run a Ramsey experiment to estimate T2* and the qubit frequency."
    },
    {
      "action_name": "auto-measure_ramsey_ramzz",
      "description": "执行 Ramsey/RamZZ 类实验以表征频率或退相干相关特性。",
      "description_en": "Run a Ramsey/RamZZ-style experiment to characterize frequency- or dephasing-related behavior."
    },
    {
      "action_name": "auto-measure_echo",
      "description": "执行 Hahn 回波实验以估计退相干时间。",
      "description_en": "Run a Hahn echo experiment to estimate dephasing time."
    },
    {
      "action_name": "auto-measure_allxy",
      "description": "执行 AllXY 实验以检查脉冲控制质量。",
      "description_en": "Run an AllXY experiment to assess pulse-control quality."
    },
    {
      "action_name": "auto-measure_ssro",
      "description": "执行单次读出表征测量。",
      "description_en": "Run a single-shot readout characterization measurement."
    },
    {
      "action_name": "auto-measure_spectroscopy",
      "description": "执行量子比特频谱扫描测量。",
      "description_en": "Run a qubit spectroscopy scan."
    },
    {
      "action_name": "auto-measure_resonator_power",
      "description": "执行谐振腔响应随功率变化的测量。",
      "description_en": "Measure resonator response as a function of power."
    },
    {
      "action_name": "auto-measure_heterodyne_spectroscopy",
      "description": "执行外差频谱测量。",
      "description_en": "Run a heterodyne spectroscopy measurement."
    },
    {
      "action_name": "auto-measure_motzoi",
      "description": "扫描 Motzoi 参数以评估脉冲整形设置。",
      "description_en": "Sweep the Motzoi parameter to evaluate pulse-shaping settings."
    },
    {
      "action_name": "auto-measure_transients",
      "description": "测量指定条件下的读出瞬态响应。",
      "description_en": "Measure readout transients for the specified cases."
    },
    {
      "action_name": "auto-calibrate_mixer_offsets_drive",
      "description": "校准驱动混频器的 I/Q 偏置。",
      "description_en": "Calibrate the I/Q offsets of the drive mixer."
    },
    {
      "action_name": "auto-calibrate_optimal_weights",
      "description": "校准读出最优积分权重。",
      "description_en": "Calibrate optimal integration weights for readout."
    },
    {
      "action_name": "auto-calibrate_MW_RO_latency",
      "description": "校准微波脉冲与读出/采集之间的时延。",
      "description_en": "Calibrate latency between microwave pulses and readout/acquisition."
    },
    {
      "action_name": "auto-calibrate_Flux_pulse_latency",
      "description": "校准通量脉冲相对微波脉冲的时序延迟。",
      "description_en": "Calibrate the timing latency of flux pulses relative to microwave pulses."
    },
    {
      "action_name": "auto-add_parameters",
      "description": "按分组规则定义该量子比特对象的参数集合。",
      "description_en": "Define the grouped parameter set for this qubit object."
    },
    {
      "action_name": "auto-add_operation",
      "description": "向操作映射中添加一个实验操作项。",
      "description_en": "Add an experimental operation entry to the operation map."
    },
    {
      "action_name": "auto-link_param_to_operation",
      "description": "将现有参数关联到某个操作参数。",
      "description_en": "Link an existing parameter to an operation argument."
    },
    {
      "action_name": "auto-add_pulse_parameter",
      "description": "为某个操作添加脉冲参数。",
      "description_en": "Add a pulse parameter to an operation."
    },
    {
      "action_name": "auto-get_operation_dict",
      "description": "获取操作字典。",
      "description_en": "Get the operation dictionary."
    },
    {
      "action_name": "auto-measure_individual_resonators",
      "description": "逐个检查谐振腔以辅助自动化识别。",
      "description_en": "Check individual resonators to support automated identification."
    },
    {
      "action_name": "auto-find_resonators",
      "description": "通过宽频扫描查找谐振腔共振凹陷。",
      "description_en": "Find resonator dips using a wide frequency scan."
    },
    {
      "action_name": "auto-find_resonator_frequency_initial",
      "description": "根据宽扫结果确定谐振腔初始频率。",
      "description_en": "Determine initial resonator frequencies from wide-scan results."
    },
    {
      "action_name": "auto-find_test_resonators",
      "description": "通过功率扫描测试谐振腔并更新其分类信息。",
      "description_en": "Test resonators with a power sweep and update their classification."
    },
    {
      "action_name": "auto-find_test_resonators_test",
      "description": "测试谐振腔并更新其分类及频率范围属性。",
      "description_en": "Test resonators and update their classification and frequency-range attributes."
    },
    {
      "action_name": "auto-find_qubit_resonator_fluxline",
      "description": "通过 DAC 扫描查找量子比特、谐振腔与通量线之间的对应关系。",
      "description_en": "Use DAC scans to find mappings between qubits, resonators, and flux lines."
    },
    {
      "action_name": "auto-find_resonator_sweetspot",
      "description": "查找谐振腔的甜点偏置点。",
      "description_en": "Find the resonator sweet-spot bias point."
    },
    {
      "action_name": "auto-find_resonator_frequency",
      "description": "通过外差频谱查找读出谐振腔频率。",
      "description_en": "Find the readout resonator frequency using heterodyne spectroscopy."
    },
    {
      "action_name": "auto-find_frequency",
      "description": "通过频谱或 Ramsey 方法查找量子比特频率。",
      "description_en": "Find the qubit frequency using spectroscopy or Ramsey methods."
    },
    {
      "action_name": "auto-calibrate_spec_pow",
      "description": "校准量子比特频谱测量的最佳功率。",
      "description_en": "Calibrate the optimal power for qubit spectroscopy."
    },
    {
      "action_name": "auto-calibrate_motzoi",
      "description": "校准 Motzoi 参数。",
      "description_en": "Calibrate the Motzoi parameter."
    },
    {
      "action_name": "auto-calibrate_frequency_ramsey",
      "description": "通过迭代 Ramsey 实验校准量子比特频率。",
      "description_en": "Calibrate the qubit frequency using iterative Ramsey experiments."
    },
    {
      "action_name": "auto-calibrate_frequency_ramsey_ramzz",
      "description": "通过迭代 Ramsey/RamZZ 实验校准频率相关参数。",
      "description_en": "Calibrate frequency-related parameters using iterative Ramsey/RamZZ experiments."
    },
    {
      "action_name": "auto-calculate_frequency",
      "description": "根据已存参数计算量子比特频率估计值。",
      "description_en": "Calculate an estimated qubit frequency from stored parameters."
    },
    {
      "action_name": "auto-tune_freq_to_sweetspot",
      "description": "将量子比特频率调到甜点附近。",
      "description_en": "Tune the qubit frequency toward its sweet spot."
    },
    {
      "action_name": "auto-tune_freq_to",
      "description": "将量子比特频率迭代调到目标值。",
      "description_en": "Iteratively tune the qubit frequency to a target value."
    }
  ]
}

